window.docContents[122].resolve({"/Types/#Type-Systems--Types___-Type-Systems--Typed-Arithmetic-Expressions--Canonical-forms":{"contents":"The following two lemmas capture the fundamental fact that the\ndefinitions of boolean and numeric values agree with the typing relation:\na well-typed value of type Bool is a boolean value, and of type Nat a\nnumeric value.\n\ntheorem bool_canonical (t : Tm) (hT : <{ ⊢ t ⦂ Bool }>) (hv : Tm.IsValue t) : Tm.IsBValue t := by\n  cases hv with\n  | inl hb => exact hb\n  | inr hn => cases hn with\n    | zero => cases hT\n    | succ t0 h => cases hT\n\ntheorem nat_canonical (t : Tm) (hT : <{ ⊢ t ⦂ Nat }>) (hv : Tm.IsValue t) : Tm.IsNValue t := by\n  cases hv with\n  | inl hb => cases hb <;> cases hT\n  | inr hn => exact hn\ntheorem bool_canonical (t : Tm) (hT : <{ ⊢ t ⦂ Bool }>) (hv : Tm.IsValue t) : Tm.IsBValue t := by\n  cases hv with\n  | inl hb => exact hb\n  | inr hn => cases hn with\n    | zero => cases hT\n    | succ t0 h => cases hT\n\ntheorem nat_canonical (t : Tm) (hT : <{ ⊢ t ⦂ Nat }>) (hv : Tm.IsValue t) : Tm.IsNValue t := by\n  cases hv with\n  | inl hb => cases hb <;> cases hT\n  | inr hn => exact hn\ntheorem bool_canonical (t : Tm) (hT : <{ ⊢ t ⦂ Bool }>) (hv : Tm.IsValue t) : Tm.IsBValue t := by\n  cases hv with\n  | inl hb => exact hb\n  | inr hn => cases hn with\n    | zero => cases hT\n    | succ t0 h => cases hT\n\ntheorem nat_canonical (t : Tm) (hT : <{ ⊢ t ⦂ Nat }>) (hv : Tm.IsValue t) : Tm.IsNValue t := by\n  cases hv with\n  | inl hb => cases hb <;> cases hT\n  | inr hn => exact hn\n\n\n","context":"Type Systems\u0009Types: Type Systems\u0009Typed Arithmetic Expressions","header":"4.1.5. Canonical forms","id":"/Types/#Type-Systems--Types___-Type-Systems--Typed-Arithmetic-Expressions--Canonical-forms"}});